import styled from '@emotion/styled';
import { theme } from 'theme';

import {
  TOOLTIP_MAX_WIDTH,
  TOOLTIP_TEXT_ALIGN_BY_POSITION,
} from './Tooltip.constants';
import type { TooltipPosition } from './Tooltip.types';

interface StyledTooltipContentProps {
  $textAlign: 'center' | 'left' | 'right';
}

export const StyledTooltipRoot = styled('div')({
  display: 'inline-flex',
});

export const StyledTooltipContent = styled('div')<StyledTooltipContentProps>(
  ({ $textAlign }) => ({
    backgroundColor: theme.colors.neutral80,
    borderRadius: theme.borderRadius['2'],
    boxShadow: '0px 1px 2px rgba(0, 0, 0, 0.16)',
    boxSizing: 'border-box',
    color: theme.colors.interfaceForegroundLabelPrimary,
    fontFamily: theme.fonts.paragraph,
    fontSize: theme.fonts.fontSizes['2'],
    fontWeight: theme.fonts.fontWeights.normal,
    lineHeight: theme.fonts.lineHeights['3'],
    maxWidth: TOOLTIP_MAX_WIDTH,
    padding: theme.spacing['2'],
    textAlign: $textAlign,
    zIndex: 1,
  }),
);

export const StyledTooltipText = styled('div')({
  display: '-webkit-box',
  overflow: 'hidden',
  WebkitBoxOrient: 'vertical',
  WebkitLineClamp: 5,
});

export const tooltipArrowStyle = {
  display: 'block',
  filter: 'drop-shadow(0px 0px 2px rgba(0, 0, 0, 0.16))',
  height: '6px',
  transform: 'translateY(-0.5px)',
  width: '12px',
  fill: theme.colors.neutral80,
} as const;

export const getTooltipTextAlign = (
  position: TooltipPosition,
): StyledTooltipContentProps['$textAlign'] =>
  TOOLTIP_TEXT_ALIGN_BY_POSITION[position];
